/**
 * Quick-start templates: a system pack, a starter scene from the shipped library and a handful
 * of tokens placed on that scene's SPAWN_* points. `applyTemplate` turns one into intents on a
 * freshly created game.
 *
 * Spawn coordinates and grid origins are hardcoded here rather than read from the GLB at apply
 * time: the scenes are generated by `scripts/make-scenes/*.mjs`, so they are known, and the game
 * is playable before the model has finished downloading. `templates.test.ts` cross-checks every
 * value against the generated files.
 */
import type { Character, Scene, Token } from '@/core/doc'
import type { AssetRef } from '@/core/assets'
import type { GridSpec, Vec3 } from '@/core/geometry'
import { newId, type AssetHash, type CharacterId, type PlayerPubkey, type SceneId, type TokenId } from '@/core/ids'
import type { Intent } from '@/core/intents'
import type { LibraryEntry } from '@/assets'
import type { RulesEngine } from '@/rules'
import { newSeed } from '@/dice'
import { LIBRARY_BASE, loadLibraryIndex } from './library'

export interface StarterToken {
  /** Key of the SPAWN_* point (without the prefix), e.g. 'player', 'barkeep'. */
  spawn: string
  name: string
  color: string
  /** Vision and light radius in cells. */
  vision: number
  light: number
  /** Roll a character sheet with the pack's chargen and link it to the token. */
  generateCharacter?: boolean
  /**
   * 'player': left unowned so a player can claim it (`token.claim`) when they join.
   * Omitted: an NPC, owned by the GM who creates the game.
   */
  owner?: 'player'
}

export interface GameTemplate {
  id: string
  name: string
  description: string
  packId: string
  /** Path inside the library (matches `LibraryEntry.path`). Omitted = no scene. */
  sceneFile?: string
  sceneName?: string
  cameraMode: Scene['cameraMode']
  darkness: number
  weather?: Scene['weather']
  ambientPreset?: Scene['ambientPreset']
  grid?: GridSpec
  /** World positions of the scene's SPAWN_* points, keyed without the prefix. */
  spawns: Record<string, Vec3>
  starterTokens: StarterToken[]
}

const SQUARE = (origin: Vec3): GridSpec => ({ type: 'square', cellSize: 1.5, origin })
const HEX_Z = 1.5 * Math.sqrt(3) / 2 // row spacing of a pointy-top hex grid with 1.5 m cells

